class Solution {
    public String addBinary(String a, String b) {
        StringBuilder reversed = new StringBuilder();
        int firstIndex = a.length() - 1;
        int secondIndex = b.length() - 1;
        int carry = 0;

        while (firstIndex >= 0 || secondIndex >= 0 || carry != 0) {
            int sum = carry;
            if (firstIndex >= 0) sum += a.charAt(firstIndex--) - '0';
            if (secondIndex >= 0) sum += b.charAt(secondIndex--) - '0';
            reversed.append((char) ('0' + sum % 2));
            carry = sum / 2;
        }

        return reversed.reverse().toString();
    }
}
